    std::string Lookup(std::string_view english_query, bool is_windows = true) const {
        std::string lower(english_query);
        std::transform(lower.begin(), lower.end(), lower.begin(), ::tolower);
        size_t s = lower.find_first_not_of(" \t\r\n");
        if (s == std::string::npos) return "";
        size_t e = lower.find_last_not_of(" \t\r\n");
        lower = lower.substr(s, e - s + 1);

        // 1. Direct O(1) exact match
        auto it = dictionary_.find(lower);
        if (it != dictionary_.end()) {
            return is_windows ? it->second.win_cmd : it->second.unix_cmd;
        }

        // 2. Strip conversational prefixes
        const std::vector<std::string> prefixes = {
            "please ", "can you ", "how to ", "i want to ", "cmd to ",
            "command to ", "tell me ", "neuroshell ", "give me ", "show me "
        };
        for (const auto& pfx : prefixes) {
            if (lower.rfind(pfx, 0) == 0) {
                std::string stripped = lower.substr(pfx.length());
                auto it2 = dictionary_.find(stripped);
                if (it2 != dictionary_.end()) {
                    return is_windows ? it2->second.win_cmd : it2->second.unix_cmd;
                }
            }
        }

        return "";
    }

    size_t size() const { return dictionary_.size(); }
